import { describe, it, expect } from "@jest/globals";
import {
  STREAK_TIERS,
  getCurrentTierIndex,
  getTierInfo,
  computeStreakTransition,
} from "./streakLogic";

describe("STREAK_TIERS", () => {
  it("is sorted ascending with the expected milestones", () => {
    expect(STREAK_TIERS).toEqual([3, 7, 14, 30, 100, 365]);
  });
});

describe("getCurrentTierIndex", () => {
  it("returns -1 below the first tier", () => {
    expect(getCurrentTierIndex(0)).toBe(-1);
    expect(getCurrentTierIndex(2)).toBe(-1);
  });

  it("matches the tier at exact milestone values", () => {
    expect(getCurrentTierIndex(3)).toBe(0);
    expect(getCurrentTierIndex(7)).toBe(1);
    expect(getCurrentTierIndex(365)).toBe(5);
  });

  it("picks the highest tier not exceeded", () => {
    expect(getCurrentTierIndex(10)).toBe(1);
    expect(getCurrentTierIndex(1000)).toBe(5);
  });
});

describe("getTierInfo", () => {
  it("reports currentTier 0 with the first tier as next below the floor", () => {
    const info = getTierInfo(1);
    expect(info.currentTier).toBe(0);
    expect(info.nextTier).toBe(3);
  });

  it("reports progress toward the next tier", () => {
    const info = getTierInfo(5);
    expect(info.currentTier).toBe(3);
    expect(info.nextTier).toBe(7);
    expect(info.tierProgress).toBeCloseTo(5 / 7, 10);
  });

  it("saturates at the top tier", () => {
    const info = getTierInfo(400);
    expect(info.currentTier).toBe(365);
    expect(info.nextTier).toBe(365);
    expect(info.tierProgress).toBe(1);
  });
});

describe("computeStreakTransition", () => {
  const base = {
    lastVisit: null,
    today: "2026-01-10",
    yesterday: "2026-01-09",
    prevCount: 0,
    prevLongest: 0,
  };

  it("starts a fresh streak at 1 with no prior visit", () => {
    expect(computeStreakTransition(base)).toEqual({
      count: 1,
      longest: 1,
      isNewDay: true,
    });
  });

  it("continues the streak when the last visit was yesterday", () => {
    expect(
      computeStreakTransition({ ...base, lastVisit: "2026-01-09", prevCount: 4, prevLongest: 6 })
    ).toEqual({ count: 5, longest: 6, isNewDay: true });
  });

  it("extends the longest when the continued streak surpasses it", () => {
    expect(
      computeStreakTransition({ ...base, lastVisit: "2026-01-09", prevCount: 6, prevLongest: 6 })
    ).toEqual({ count: 7, longest: 7, isNewDay: true });
  });

  it("is a no-op when visiting again on the same day", () => {
    expect(
      computeStreakTransition({ ...base, lastVisit: "2026-01-10", prevCount: 5, prevLongest: 9 })
    ).toEqual({ count: 5, longest: 9, isNewDay: false });
  });

  it("resets to 1 after a gap of more than one day", () => {
    expect(
      computeStreakTransition({ ...base, lastVisit: "2026-01-07", prevCount: 3, prevLongest: 8 })
    ).toEqual({ count: 1, longest: 8, isNewDay: true });
  });

  it("resets to 1 after a gap crossing from yesterday back to today", () => {
    expect(
      computeStreakTransition({ ...base, lastVisit: "2026-01-08", prevCount: 2, prevLongest: 2 })
    ).toEqual({ count: 1, longest: 2, isNewDay: true });
  });

  it("never reduces longest on reset", () => {
    expect(
      computeStreakTransition({ ...base, lastVisit: "2026-01-01", prevCount: 1, prevLongest: 30 })
    ).toEqual({ count: 1, longest: 30, isNewDay: true });
  });
});

import { describe, it, expect, jest, afterEach, beforeEach } from "@jest/globals";
import { renderHook, waitFor } from "@testing-library/react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { useStreak, getStreakFromStorage } from "./useStreak";

const RealDate = global.Date;
let clock: number;

function mockClock(iso: string) {
  clock = new RealDate(iso).getTime();
}

beforeEach(() => {
  mockClock("2026-01-10T12:00:00.000Z");
  jest.spyOn(global, "Date").mockImplementation(
    ((...args: unknown[]) =>
      args.length === 0 ? new RealDate(clock) : new RealDate(...(args as []))) as unknown as typeof RealDate
  );
  jest.spyOn(global.Date, "now").mockReturnValue(clock);
});

afterEach(async () => {
  jest.restoreAllMocks();
  await AsyncStorage.clear();
});

describe("useStreak", () => {
  it("starts a fresh streak and persists the visit", async () => {
    const { result } = renderHook(() => useStreak());
    await waitFor(() => expect(result.current.count).toBe(1));
    expect(result.current.longest).toBe(1);
    expect(result.current.isNewDay).toBe(true);
    expect(await AsyncStorage.getItem("streak_count")).toBe("1");
    expect(await AsyncStorage.getItem("streak_last_visit")).toBe("2026-01-10");
    expect(await AsyncStorage.getItem("streak_longest")).toBe("1");
  });

  it("continues an existing streak visited yesterday", async () => {
    await AsyncStorage.setItem("streak_count", "4");
    await AsyncStorage.setItem("streak_longest", "6");
    await AsyncStorage.setItem("streak_last_visit", "2026-01-09");
    const { result } = renderHook(() => useStreak());
    await waitFor(() => expect(result.current.count).toBe(5));
    expect(result.current.longest).toBe(6);
    expect(result.current.isNewDay).toBe(true);
  });

  it("extends longest when the streak surpasses the previous record", async () => {
    await AsyncStorage.setItem("streak_count", "6");
    await AsyncStorage.setItem("streak_longest", "6");
    await AsyncStorage.setItem("streak_last_visit", "2026-01-09");
    const { result } = renderHook(() => useStreak());
    await waitFor(() => expect(result.current.count).toBe(7));
    expect(result.current.longest).toBe(7);
  });

  it("is a no-op on a same-day visit", async () => {
    await AsyncStorage.setItem("streak_count", "4");
    await AsyncStorage.setItem("streak_longest", "4");
    await AsyncStorage.setItem("streak_last_visit", "2026-01-10");
    const { result } = renderHook(() => useStreak());
    await waitFor(() => expect(result.current.count).toBe(4));
    expect(result.current.isNewDay).toBe(false);
    expect(await AsyncStorage.getItem("streak_last_visit")).toBe("2026-01-10");
  });

  it("resets to 1 after a gap longer than a day", async () => {
    await AsyncStorage.setItem("streak_count", "9");
    await AsyncStorage.setItem("streak_longest", "30");
    await AsyncStorage.setItem("streak_last_visit", "2026-01-05");
    const { result } = renderHook(() => useStreak());
    await waitFor(() => expect(result.current.count).toBe(1));
    expect(result.current.longest).toBe(30);
    expect(result.current.isNewDay).toBe(true);
  });

  it("reports tier info for the current count", async () => {
    await AsyncStorage.setItem("streak_count", "5");
    await AsyncStorage.setItem("streak_longest", "5");
    await AsyncStorage.setItem("streak_last_visit", "2026-01-09");
    const { result } = renderHook(() => useStreak());
    await waitFor(() => expect(result.current.currentTier).toBe(3));
    expect(result.current.nextTier).toBe(7);
    expect(result.current.tierProgress).toBeCloseTo(5 / 7, 10);
  });

  it("consumes a pending toast exactly once", async () => {
    await AsyncStorage.setItem("streak_toast_pending", "true");
    const { result } = renderHook(() => useStreak());
    await waitFor(() => expect(result.current.count).toBe(1));
    const toast = await result.current.consumePendingToast();
    expect(toast?.count).toBe(1);
    expect(await AsyncStorage.getItem("streak_toast_pending")).toBeNull();
    expect(await result.current.consumePendingToast()).toBeNull();
  });

  it("returns null from consumePendingToast when nothing is pending", async () => {
    const { result } = renderHook(() => useStreak());
    await waitFor(() => expect(result.current.count).toBe(1));
    expect(await result.current.consumePendingToast()).toBeNull();
  });
});

describe("getStreakFromStorage", () => {
  it("returns persisted values, defaulting to zero", async () => {
    expect(await getStreakFromStorage()).toEqual({ count: 0, longest: 0 });
    await AsyncStorage.setItem("streak_count", "3");
    await AsyncStorage.setItem("streak_longest", "9");
    expect(await getStreakFromStorage()).toEqual({ count: 3, longest: 9 });
  });
});

import { describe, it, expect, jest, afterEach, beforeEach } from "@jest/globals";
import AsyncStorage from "@react-native-async-storage/async-storage";
import {
  recordCompletion,
  getUnlockedAchievements,
  getUnlockedAchievementsAt,
  ACHIEVEMENTS,
} from "./useAchievements";

const RealDate = global.Date;
let clock: number;

function setClock(iso: string) {
  clock = new RealDate(iso).getTime();
}

function advanceMinutes(minutes: number) {
  clock += minutes * 60 * 1000;
}

beforeEach(() => {
  setClock("2026-01-10T12:00:00.000Z");
  jest.spyOn(global, "Date").mockImplementation(
    ((...args: unknown[]) =>
      args.length === 0 ? new RealDate(clock) : new RealDate(...(args as []))) as unknown as typeof RealDate
  );
  jest.spyOn(global.Date, "now").mockReturnValue(clock);
});

afterEach(async () => {
  jest.restoreAllMocks();
  await AsyncStorage.clear();
});

describe("ACHIEVEMENTS catalog", () => {
  it("defines the five known achievements with unique ids", () => {
    const ids = ACHIEVEMENTS.map((a) => a.id);
    expect(ids).toEqual([
      "first-strokes",
      "daily-3",
      "quickdraw",
      "on-a-roll",
      "weekender",
    ]);
    expect(new Set(ids).size).toBe(ids.length);
    for (const a of ACHIEVEMENTS) {
      expect(a.title.length).toBeGreaterThan(0);
      expect(a.icon.length).toBeGreaterThan(0);
    }
  });
});

describe("recordCompletion", () => {
  it("unlocks first-strokes on the first completion", async () => {
    const newly = await recordCompletion("ex-a");
    expect(newly).toContain("first-strokes");
    expect(await getUnlockedAchievements()).toContain("first-strokes");
  });

  it("unlocks daily-3 after three distinct exercises on the same day", async () => {
    await recordCompletion("ex-a");
    await recordCompletion("ex-b");
    const newly = await recordCompletion("ex-c");
    expect(newly).toContain("daily-3");
  });

  it("does not count the same exercise twice on one day", async () => {
    await recordCompletion("ex-a");
    await recordCompletion("ex-a");
    await recordCompletion("ex-b");
    const newly = await recordCompletion("ex-b");
    expect(newly).not.toContain("daily-3");
  });

  it("counts the same exercise again on a different day", async () => {
    await recordCompletion("ex-a");
    await recordCompletion("ex-a"); // same day, ignored
    await recordCompletion("ex-b");
    advanceMinutes(60 * 24); // next day
    const newly = await recordCompletion("ex-a");
    expect(newly).toContain("daily-3");
  });

  it("unlocks quickdraw for a completion under 30 seconds", async () => {
    const newly = await recordCompletion("ex-a", 20000);
    expect(newly).toContain("quickdraw");
  });

  it("does not unlock quickdraw for slow completions", async () => {
    await recordCompletion("ex-a", 60000);
    expect(await getUnlockedAchievements()).not.toContain("quickdraw");
  });

  it("unlocks on-a-roll when three completions land within ten minutes", async () => {
    await recordCompletion("ex-a", 1000);
    advanceMinutes(5);
    await recordCompletion("ex-b", 1000);
    advanceMinutes(5);
    const newly = await recordCompletion("ex-c", 1000);
    expect(newly).toContain("on-a-roll");
  });

  it("does not unlock on-a-roll when completions span more than ten minutes", async () => {
    await recordCompletion("ex-a");
    advanceMinutes(6);
    await recordCompletion("ex-b");
    advanceMinutes(6);
    await recordCompletion("ex-c");
    expect(await getUnlockedAchievements()).not.toContain("on-a-roll");
  });

  it("unlocks weekender when the streak has reached seven", async () => {
    await AsyncStorage.setItem("streak_count", "7");
    const newly = await recordCompletion("ex-a");
    expect(newly).toContain("weekender");
  });

  it("does not unlock weekender below a seven-day streak", async () => {
    await AsyncStorage.setItem("streak_count", "6");
    await recordCompletion("ex-a");
    expect(await getUnlockedAchievements()).not.toContain("weekender");
  });

  it("is idempotent and never re-reports an unlocked badge", async () => {
    const first = await recordCompletion("ex-a");
    const again = await recordCompletion("ex-b");
    expect(again).not.toContain("first-strokes");
    expect(first).toContain("first-strokes");
  });

  it("records unlock timestamps", async () => {
    await recordCompletion("ex-a");
    const at = await getUnlockedAchievementsAt();
    expect(Object.keys(at)).toContain("first-strokes");
    expect(at["first-strokes"]).toMatch(/^\d{4}-\d{2}-\d{2}T/);
  });
});

