import { describe, it, expect, jest, beforeEach } from "@jest/globals";
import { render, fireEvent } from "@testing-library/react-native";
import Button from "./Button";
import { renderWithProviders } from "../test/renderWithProviders";

describe("Button", () => {
  const onPress = jest.fn();

  beforeEach(() => {
    onPress.mockClear();
  });

  it("renders the title and fires onPress when pressed", () => {
    const { getByText } = renderWithProviders(
      <Button title="Go" onPress={onPress} />
    );
    fireEvent.press(getByText("Go"));
    expect(onPress).toHaveBeenCalledTimes(1);
  });

  it("uses the title as the default accessibility label", () => {
    const { getByLabelText } = renderWithProviders(
      <Button title="Start" onPress={onPress} />
    );
    expect(getByLabelText("Start")).toBeTruthy();
  });

  it("honors an explicit accessibilityLabel", () => {
    const { getByLabelText } = renderWithProviders(
      <Button title="Start" onPress={onPress} accessibilityLabel="Launch" />
    );
    expect(getByLabelText("Launch")).toBeTruthy();
  });

  it("does not fire when disabled", () => {
    const { getByLabelText } = renderWithProviders(
      <Button title="Start" onPress={onPress} disabled />
    );
    fireEvent.press(getByLabelText("Start"));
    expect(onPress).not.toHaveBeenCalled();
  });

  it("renders both variants without throwing", () => {
    renderWithProviders(<Button title="Primary" onPress={onPress} variant="primary" />);
    renderWithProviders(<Button title="Outline" onPress={onPress} variant="outline" />);
  });
});

import { describe, it, expect, jest, beforeEach } from "@jest/globals";
import { render, fireEvent } from "@testing-library/react-native";
import Breadcrumbs from "./Breadcrumbs";
import { renderWithProviders } from "../test/renderWithProviders";
import { mockRouterModule, mockRouter } from "../test/expoRouterMock";

jest.mock("expo-router", () => mockRouterModule);

describe("Breadcrumbs", () => {
  beforeEach(() => {
    mockRouter.push.mockClear();
  });

  it("renders every segment label", () => {
    const { getByText } = renderWithProviders(
      <Breadcrumbs
        segments={[
          { label: "Courses", href: "/" },
          { label: "Shapes", href: "/courses/shapes" },
          { label: "Circles" },
        ]}
      />
    );
    expect(getByText("Courses")).toBeTruthy();
    expect(getByText("Shapes")).toBeTruthy();
    expect(getByText("Circles")).toBeTruthy();
  });

  it("navigates to a href when a non-last segment is pressed", () => {
    const { getByLabelText } = renderWithProviders(
      <Breadcrumbs
        segments={[
          { label: "Courses", href: "/" },
          { label: "Shapes" },
        ]}
      />
    );
    fireEvent.press(getByLabelText("Go to Courses"));
    expect(mockRouter.push).toHaveBeenCalledWith("/");
  });

  it("does not make the last segment clickable", () => {
    const { queryByLabelText } = renderWithProviders(
      <Breadcrumbs
        segments={[
          { label: "Courses", href: "/" },
          { label: "Shapes", href: "/courses/shapes" },
        ]}
      />
    );
    expect(queryByLabelText("Go to Shapes")).toBeNull();
  });
});

import { describe, it, expect } from "@jest/globals";
import { screen, render } from "@testing-library/react-native";
import { MaterialCommunityIcons } from "@expo/vector-icons";
import ModuleCover from "./ModuleCover";
import { renderWithProviders } from "../test/renderWithProviders";

describe("ModuleCover", () => {
  it("renders a lock icon when locked", () => {
    renderWithProviders(<ModuleCover slug="shapes" color="#ED225D" locked />);
    expect(screen.UNSAFE_queryAllByType(MaterialCommunityIcons).length).toBe(1);
  });

  it("renders a check icon when completed", () => {
    renderWithProviders(<ModuleCover slug="shapes" color="#ED225D" completed />);
    expect(screen.UNSAFE_queryAllByType(MaterialCommunityIcons).length).toBe(1);
  });

  it("renders the animated variant for unlocked covers (no icon)", () => {
    renderWithProviders(<ModuleCover slug="shapes" color="#ED225D" />);
    expect(screen.UNSAFE_queryAllByType(MaterialCommunityIcons).length).toBe(0);
  });

  it("falls back to the default variant for unknown slugs", () => {
    expect(() =>
      renderWithProviders(<ModuleCover slug="unknown-slug" color="#ED225D" />)
    ).not.toThrow();
  });

  it("renders without a provider tree when passed minimal props", () => {
    expect(() =>
      render(<ModuleCover slug="math" color="#000000" />)
    ).not.toThrow();
  });
});

import { describe, it, expect, jest, beforeEach } from "@jest/globals";
import { render, fireEvent } from "@testing-library/react-native";
import ExerciseCard from "./ExerciseCard";
import { renderWithProviders } from "../test/renderWithProviders";

describe("ExerciseCard", () => {
  const onContinue = jest.fn();

  beforeEach(() => {
    onContinue.mockClear();
  });

  it("renders title, module name and description", () => {
    const { getByText } = renderWithProviders(
      <ExerciseCard
        title="Circles"
        moduleName="Shapes"
        description="Draw a circle."
      />
    );
    expect(getByText("Circles")).toBeTruthy();
    expect(getByText("Shapes")).toBeTruthy();
    expect(getByText("Draw a circle.")).toBeTruthy();
